ST.xhtml:p:
(*BS04K的XML与BS12K是一样的，区别BS04K没有聚焦镜温度，需屏蔽，BS04K需要零焦偏置15左右，焦点范围不同+12~-15*)
(*心跳包，写入0x3A，保证使能*)
g_noHeart_Beat := 58;

R_Trigger(CLK := g_bF050Home );

(*回零,F轴到0刻度*)
IF R_Trigger.Q THEN
  g_bF050Home := false; 
  g_noPositionSetFocus := LREAL_TO_DINT(1000.0*g_dZeroFActPosion);    
END_IF;


IF g_bBS04KEnable THEN
  dFPosFb := g_dAnalogPosition;
  g_bBS04KEnable := FALSE;
  g_bFocusEnable := FALSE;
  nState := 5;
ELSIF g_bMnualAnalogEnable THEN
  dFPosFb := g_dMnualAnalogPosition;
  g_bMnualAnalogEnable := FALSE;
  nState := 5;
END_IF;

CASE nState OF
  0:
    nState := 0;
  5:  (*步进电机调焦*)
    g_dMOTO_PositionSet := 1000.0*g_dZeroFActPosion - 1000.0*dFPosFb;
    g_noPositionSetFocus := LREAL_TO_DINT(g_dMOTO_PositionSet);
    FocusTon(IN := FALSE,PT := T#5s);
    nState := 10;      
  10:(*调焦完成*)    
    IF g_niBS12KActualFocus>g_noPositionSetFocus-50 AND g_niBS12KActualFocus< g_noPositionSetFocus+50 THEN
      g_bFocusDone := TRUE;
      nState := 0;
    END_IF;
    FocusTon(IN := TRUE,PT := T#5s);
    IF FocusTon.Q THEN  (*调焦超时报警*)
      FocusTon.IN := FALSE;
      g_bFocusOvertimeAlarm := TRUE;
      nState := 0;
    END_IF;
END_CASE;    




(*坐标反馈*)
g_dFaxisAnoagePosFb := (1000.0*g_dZeroFActPosion - DINT_TO_LREAL(g_niBS12KActualFocus))/1000.0;

(*第一次出光记录下保护镜温度*)
IF g_nBottomProtectiveWindowTemper1 = 0 THEN  (*初始化下保护镜记录温度*)
  g_nBottomProtectiveWindowTemper1 := g_niBS12KBottomProtectiveWindowTemper;
END_IF;

R_Trigger1(CLK := g_bOProcessStart );
IF R_Trigger1.Q THEN
  RiseState := 5;
  Ton1(IN := FALSE,PT := T#100ms);
END_IF;

CASE RiseState OF
  0:
    RiseState := 0;
  5:(*出光后100ms记录下保护镜温度*)
    Ton1(IN := g_bLaserCuttingEnable,PT := T#100ms);
    IF Ton1.Q THEN
      g_nBottomProtectiveWindowTemper1 := g_niBS12KBottomProtectiveWindowTemper;
      Ton1(IN := FALSE);
      RiseState := 0;
    END_IF;
END_CASE;


(*调焦头使能警，0异常，1正常*)
ToFAlarm202(IN := g_niBS12KStatusEnable = 0, PT := T#1s);    
IF ToFAlarm202.Q THEN
  IF g_bCloseEnableAlarm_BS12K THEN
     g_Alarm.alarmArray[357] := 0; 
  ELSE
    g_Alarm.alarmArray[357] := 1085;  
  END_IF;
ELSE
  g_Alarm.alarmArray[357] := 0;  
END_IF;  
(*上保护镜温度报警*)
ToFAlarm203(IN := g_niBS12KTopProtectiveWindowTemperAlarm = 0, PT := T#1s);    
IF ToFAlarm203.Q THEN
  IF  g_bCloseUpProtectWindowAlarm_BS12K  THEN
    g_Alarm.alarmArray[358] := 0; 
  ELSE
    g_Alarm.alarmArray[358] := 1086;  
  END_IF; 
ELSE
  g_Alarm.alarmArray[358] := 0; 
END_IF; 
(*腔体温度报警*)
ToFAlarm204(IN := g_niBS12KCavityTemperatureAlarm = 0, PT := T#1s);  
IF ToFAlarm204.Q THEN
  IF  g_bClosedCavityTemperatureAlarm_BS12K THEN
    g_Alarm.alarmArray[359] := 0; 
  ELSE
    g_Alarm.alarmArray[359] := 1087;  
  END_IF; 
ELSE
  g_Alarm.alarmArray[359] := 0; 
END_IF;
(*下保护镜温度报警*)   
ToFAlarm206(IN := g_niBS12KBottomProtectiveWindowTemperAlarm = 0, PT := T#1s); 
IF ToFAlarm206.Q THEN
  IF  g_bCloseDownProtectWindowAlarm_BS12K THEN
    g_Alarm.alarmArray[360] := 0; 
  ELSE
    g_Alarm.alarmArray[360] := 1088; 
  END_IF;
ELSE
  g_Alarm.alarmArray[360] := 0;  
END_IF;
(*腔体压力报警*)
ToFAlarm207(IN := g_niBS12KCavityAlarmPressure = 0, PT := T#1s); 
IF ToFAlarm207.Q THEN
  IF  g_bCloseCavityPressureAlarm_BS12K THEN
    g_Alarm.alarmArray[364] := 0; 
  ELSE
    g_Alarm.alarmArray[364] := 1092;
  END_IF;
ELSE
  g_Alarm.alarmArray[364] := 0;   
END_IF;
(*下保护镜到位报警信号*)  
ToFAlarm209(IN := g_niBS12KBottomProtectiveWindowInPosition = 0, PT := T#1s); 
IF ToFAlarm209.Q THEN
  IF  g_bCloseDownProtectWindowInPosAlarm_BS12K THEN
    g_Alarm.alarmArray[365] := 0; 
  ELSE
     g_Alarm.alarmArray[365] := 1093; 
  END_IF; 
ELSE
  g_Alarm.alarmArray[365] := 0;
END_IF; 
(*电机故障代码*)  
ToFAlarm210(IN := g_niBS12KFocusMotorErrorCode <>0, PT := T#1s);  
IF ToFAlarm210.Q THEN  
  g_Alarm.alarmArray[361] := 1089;    
ELSE
  g_Alarm.alarmArray[361] := 0;  
END_IF;
(*调焦头WIFI报警*)   
ToFAlarm213(IN := g_niBS12KStatusWIF = 0, PT := T#1s); 
IF ToFAlarm213.Q THEN
  IF g_bCloseWIFIAlarm_BS12K THEN
    g_Alarm.alarmArray[362] := 0; 
  ELSE
    g_Alarm.alarmArray[362] := 1090;  
  END_IF; 
ELSE
  g_Alarm.alarmArray[362] := 0; 
END_IF;
